        data: {"result": {"minY": 1.0, "minX": 0.0, "maxY": 1242.0, "series": [{"data": [[0.0, 1242.0]], "isOverall": false, "label": "GET /titulos", "isController": false}, {"data": [[0.0, 1230.0]], "isOverall": false, "label": "GET /prestamos", "isController": false}, {"data": [[0.0, 1223.0]], "isOverall": false, "label": "GET /avisos", "isController": false}, {"data": [[0.0, 1226.0]], "isOverall": false, "label": "POST /prestamos/{id}/devolucion", "isController": false}, {"data": [[0.0, 1240.0]], "isOverall": false, "label": "GET /titulos/{id}", "isController": false}, {"data": [[0.0, 1234.0]], "isOverall": false, "label": "POST /prestamos (multi-paso)", "isController": false}, {"data": [[0.0, 1235.0]], "isOverall": false, "label": "POST /usuarios", "isController": false}, {"data": [[1400.0, 1.0]], "isOverall": false, "label": "setup - token client_credentials", "isController": false}, {"data": [[0.0, 1.0]], "isOverall": false, "label": "setup - crear título de carga", "isController": false}], "supportsControllersDiscrimination": true, "granularity": 100, "maxX": 1400.0, "title": "Response Time Distribution"}},
